// Regression checks for browser code generated by the extension. Compile first.
const assert = require('assert/strict');
const vm = require('vm');
const Module = require('module');
const { getChartScript } = require('./out/chartTemplate');
const { escapeHtml, serializeForScript } = require('./out/webviewHtml');
assert.equal(escapeHtml('<a> & \"'), '&lt;a&gt; &amp; &quot;');
assert.equal(serializeForScript({ metric: '</script><img>' }).includes('</script>'), false);
assert.deepEqual(JSON.parse(serializeForScript({ metric: '</script><img>' })), { metric: '</script><img>' });
const originalLoad = Module._load;
let MultiRunViewerPanel;
try {
    Module._load = function(name, ...args) {
        return name === 'vscode' ? {} : originalLoad.call(this, name, ...args);
    };
    ({ MultiRunViewerPanel } = require('./out/MultiRunViewerPanel'));
} finally {
    Module._load = originalLoad;
}
const { MultiRunManager } = require('./out/MultiRunManager');

const script = getChartScript();
new vm.Script(script);
const context = vm.createContext({
    Chart: { Interaction: { modes: {} }, helpers: { getRelativePosition: event => event } }
});
// Execute the generated interaction code without requiring a DOM or Chart.js.
vm.runInContext(script.slice(
    script.indexOf('Chart.Interaction.modes.runX ='),
    script.indexOf('function fitYAxisToVisibleX(')
), context);
const datasets = [
    { data: [{ x: 0, y: 10 }, { x: 50, y: 5 }, { x: 100, y: 1 }] },
    { data: [{ x: 0, y: 9 }, { x: 5, y: 7 }, { x: 10, y: 6 }] },
    { _isRaw: true, data: [{ x: 0, y: 4 }, { x: 100, y: 2 }] },
    { hidden: true, data: [{ x: 0, y: 4 }, { x: 100, y: 2 }] }
];
let pixelForX = x => x;
const metas = datasets.map((dataset, index) => ({
    index,
    controller: { getParsed: pointIndex => dataset.data[pointIndex] },
    data: dataset.data.map(point => ({
        getProps: () => ({ x: pixelForX(point.x), y: point.y })
    }))
}));
const chart = {
    data: { datasets },
    chartArea: { left: 0, right: 100, top: 0, bottom: 100 },
    scales: { x: { getValueForPixel: x => x } },
    getSortedVisibleDatasetMetas: () => metas.filter(meta => !datasets[meta.index].hidden)
};
const pick = x => Array.from(context.Chart.Interaction.modes.runX(chart, { x, y: 50 }, {}, true),
    item => [item.datasetIndex, item.index]);
assert.deepEqual(pick(50), [[0, 1]]); // Short run ends at X=10, not halfway across the canvas.
assert.deepEqual(pick(6), [[0, 0], [1, 1]]); // Independent logging frequencies.
assert.deepEqual(pick(10), [[0, 0], [1, 2]]);
assert.deepEqual(pick(-1), []);
assert.deepEqual(pick(101), []);
chart.scales.x.getValueForPixel = x => 10 ** (x / 50);
pixelForX = x => x > 0 ? Math.log10(x) * 50 : NaN;
assert.deepEqual(pick(25), [[0, 1], [1, 1]]); // Logarithmic distance, skipping invalid X=0.

const panel = Object.create(MultiRunViewerPanel.prototype);
panel._folderPaths = new Set(['/tmp/synthetic-runs']);
panel._manager = new MultiRunManager('/tmp/synthetic-runs');
const source = (runId, data) => ({
    runId, runName: runId, runGroup: 'experiment', color: '#ff0000', data
});
const training = [
    { metricName: 'loss', datasets: [source('run1', [
        { step: 0, value: 5 }, { step: 5, value: 4 }, { step: 15, value: 2 }, { step: 30, value: 1 }
    ])] },
    { metricName: 'images_seen', datasets: [source('run1', [
        { step: 0, value: 0 }, { step: 10, value: 100 }, { step: 20, value: 200 }
    ])] }
];
const init = panel._generateChartInitScript({ training, system: [], summary: [] });
new vm.Script(init);
const customContext = vm.createContext({
    trainingMetrics: training, summaryMetrics: [], groupWandbRuns: false,
    numericRunConfigs: { run1: { 'trainer.batch_size': 2 } }
});
vm.runInContext(init.slice(
    init.indexOf('function getCustomSourceMetrics('),
    init.indexOf('function formatCustomAxisLabel(')
), customContext);
const definition = { id: 'images-loss', title: 'Loss over images', xMetric: 'images_seen', yMetric: 'loss' };
const customMetric = customContext.buildCustomMetric(definition);
assert.equal(customMetric.datasets[0].runName, 'run1');
assert.deepEqual(Array.from(customMetric.datasets[0].data, p => [p.step, p.value]), [[0, 5], [50, 4], [150, 2]]);
const scaled = customContext.buildCustomMetric({ ...definition, xMultiplierConfig: 'trainer.batch_size' });
assert.deepEqual(Array.from(scaled.datasets[0].data, p => p.step), [0, 100, 300]);
assert.equal(customContext.buildCustomMetric({ ...definition, xMultiplierConfig: 'missing' }).datasets.length, 0);
customContext.groupWandbRuns = true;
assert.equal(customContext.buildCustomMetric(definition).datasets[0].runName, 'experiment');

// W&B automatically summarizes logged training metrics. Creating a custom plot
// must retain its selected time series even when a summary of the same key exists.
customContext.summaryMetrics = [{
    metricName: 'summary/loss',
    datasets: [source('run1', [{ step: 30, value: 1 }])]
}];
Object.assign(customContext, {
    chartInstances: {},
    customPlotDefinitions: [{ ...definition, xMultiplierConfig: 'trainer.batch_size' }],
    customMetrics: [],
    document: { getElementById: () => null },
    updatePersistedViewState: () => {},
    updateCustomPlotBuilderOptions: () => {}
});
vm.runInContext(init.slice(
    init.indexOf('function renderCustomPlots('),
    init.indexOf('function createCustomPlot(')
), customContext);
customContext.renderCustomPlots();
assert.equal(customContext.customPlotDefinitions[0].xMetric, 'images_seen');
assert.equal(customContext.customPlotDefinitions[0].yMetric, 'loss');
assert.equal(customContext.customPlotDefinitions[0].xMultiplierConfig, 'trainer.batch_size');
assert.equal(customContext.customMetrics[0].datasets[0].data.length, 3);

// A temporarily unavailable Y series must not reset a metric-vs-metric plot.
const savedTraining = customContext.trainingMetrics;
customContext.trainingMetrics = savedTraining.filter(metric => metric.metricName !== 'loss');
customContext.renderCustomPlots();
assert.equal(customContext.customPlotDefinitions[0].xMetric, 'images_seen');
assert.equal(customContext.customPlotDefinitions[0].yMetric, 'loss');
customContext.trainingMetrics = savedTraining;
customContext.renderCustomPlots();
assert.equal(customContext.customMetrics[0].datasets[0].data.length, 3);

customContext.customPlotDefinitions = [{ ...definition, yMetric: 'summary/loss' }];
customContext.renderCustomPlots();
assert.equal(customContext.customPlotDefinitions[0].xMetric, '_step');
assert.equal(customContext.customMetrics[0].datasets[0].data.length, 1);

const retainedCustomChart = {};
const updatedCharts = [];
Object.assign(customContext, {
    customPlotDefinitions: [definition],
    chartInstances: { customCanvas: retainedCustomChart },
    document: { getElementById: () => ({ dataset: {
        chartType: 'custom', chartStateKey: definition.id
    } }) },
    updateChartData: (chart, metric) => updatedCharts.push({ chart, metric }),
    modalChart: null,
    renderCustomPlots: () => { throw new Error('Live updates must retain custom chart DOM'); }
});
vm.runInContext(init.slice(
    init.indexOf('function getMetricsForType('),
    init.indexOf('function getCustomSourceMetrics(')
), customContext);
vm.runInContext(init.slice(
    init.indexOf('function updateMergedMetrics('),
    init.indexOf('function updateRunNamesInCharts(')
), customContext);
customContext.updateMergedMetrics({ training, system: [], summary: [] });
assert.equal(updatedCharts[0].chart, retainedCustomChart);
assert.equal(updatedCharts[0].metric.customPlotId, definition.id);
assert.equal(customContext.chartInstances.customCanvas, retainedCustomChart);

const html = panel._generateMetricsHtml(training, 'training');
assert.equal((html.match(/class="charts-grid"/g) || []).length, 1);
assert.equal(html.includes('metric-group'), false);
assert.ok(html.includes('data-metric-name="images_seen"'));
console.log('Chart interactions, custom X axes, config multipliers, and flat grids passed.');

async function testLiveUpdateMessages() {
    const viewer = Object.create(MultiRunViewerPanel.prototype);
    let htmlAssignments = 0;
    const messages = [];
    const webview = { postMessage: async message => { messages.push(message); return true; } };
    Object.defineProperty(webview, 'html', { set: () => { htmlAssignments++; } });
    let mergedMetrics = { training, system: [], summary: [] };
    Object.assign(viewer, {
        _panel: { visible: true, webview },
        _manager: {
            parseSelectedRuns: async () => {},
            getSelectedRunIds: () => [],
            getRuns: () => []
        },
        _getMergedMetrics: () => mergedMetrics,
        _folderPaths: new Set(['/tmp/synthetic-runs']),
        _comparisonGroups: [], _customWandbGroupColors: {},
        _customRunNames: {}, _defaultRunSort: 'created-desc', _chartColumns: 1,
        _renderedMetricSignature: '', _hasRenderedWebview: false,
        _scheduleContentInspection: () => {},
        _loadComparisonGroups: async () => {},
        _scanFolders: async () => [],
        _pendingFileChanges: new Map(), _disposed: false
    });
    await viewer._update(false);
    assert.equal(htmlAssignments, 1);
    mergedMetrics = { ...mergedMetrics, training: [
        ...training, { metricName: 'new/loss', datasets: training[0].datasets }
    ] };
    await viewer._refreshRunDataInWebview();
    assert.equal(htmlAssignments, 1);
    assert.equal(messages.at(-1).command, 'runDataUpdated');
    assert.ok(messages.at(-1).chartHtml.training.includes('new/loss'));
    await viewer._refreshRunDataInWebview();
    assert.equal(messages.at(-1).chartHtml, undefined);
    mergedMetrics = { training: [], system: [], summary: [] };
    await viewer._refreshSelectionInWebview();
    assert.equal(messages.at(-1).command, 'runSelectionDataUpdated');
    assert.equal(htmlAssignments, 1);
    viewer._pendingFileChanges.set('/tmp/synthetic-runs/new.wandb', { type: 'added' });
    await viewer._processPendingFileChanges();
    assert.equal(messages.at(-1).command, 'runListUpdated');
    assert.equal(htmlAssignments, 1);
    console.log('Live updates, first metrics, selection changes, and run discovery retain the webview.');

    const manager = new MultiRunManager('/tmp/synthetic-runs');
    const metadata = { runId: 'live', runName: 'live', filePath: '/tmp/synthetic-runs/live.wandb',
        isVisible: true, lastModified: 1, fileSize: 100 };
    manager.addRun(metadata);
    manager.getState().parsedData.set('live', {
        runId: 'live', config: {}, systemMetrics: {},
        metrics: { loss: [{ step: 0, value: 1 }, { step: 1, value: 0.5 }] }
    });
    viewer._manager = manager;
    viewer._getMergedMetrics = () => manager.mergeMetrics();
    viewer._getImageViewerData = () => [];
    viewer._renderedMetricSignature = viewer._getMetricSignature(manager.mergeMetrics());
    // Reproduce a watcher event arriving in the await between parsing and merge.
    const refresh = viewer._refreshRunDataInWebview();
    manager.updateRun({ ...metadata, lastModified: 2, fileSize: 200 });
    await refresh;
    assert.equal(messages.at(-1).mergedMetrics.training.length, 1);
    assert.equal(messages.at(-1).chartHtml, undefined, 'an invalidation during refresh must not send chart-removal HTML');
    assert.equal(htmlAssignments, 1);
    manager.deselectAll();
    await viewer._refreshSelectionInWebview();
    assert.equal(messages.at(-1).mergedMetrics.training.length, 0);
    assert.ok(messages.at(-1).chartHtml.training.includes('No metrics found'), 'explicit deselection still removes charts');
    console.log('Watcher invalidation between parsing and merging retains chart panels.');
}

testLiveUpdateMessages().catch(error => {
    console.error(error);
    process.exitCode = 1;
});
